class TypeResolver:
    """Derives a type and a :class:`Sort` for every value in an operation tree."""

    #: Safety net for the fixed-point loop.
    MAX_ITERATIONS = 8

    def __init__(
        self,
        root: Operation,
        symbols: Optional[SymbolResolution] = None,
    ) -> None:
        self.root = root
        self.symbols = symbols if symbols is not None else SymbolResolver(root).resolve()
        self._resolution: Optional[TypeResolution] = None

    # -- entry point ------------------------------------------------------
    def resolve(self) -> TypeResolution:
        """Run the analysis (cached: repeated calls return the same result)."""
        if self._resolution is not None:
            return self._resolution

        resolution = TypeResolution()
        self._collect_signatures(resolution)
        self._seed_declared_types(resolution)

        for iteration in range(1, self.MAX_ITERATIONS + 1):
            resolution.iterations = iteration
            if not self._infer_once(resolution):
                break

        self._resolution = resolution
        return resolution

    # -- signatures -------------------------------------------------------
    def _collect_signatures(self, resolution: TypeResolution) -> None:
        for name, entry in self.symbols.definitions.items():
            op = entry.op
            if op is None:
                continue
            attr = op.attributes.get("function_type")
            if isinstance(attr, TypeAttr) and isinstance(attr.value, FunctionType):
                resolution.signatures[name] = attr.value

    # -- declared types ---------------------------------------------------
    def _seed_declared_types(self, resolution: TypeResolution) -> None:
        env = resolution.environment

        def visit(op: Operation) -> None:
            scope = self._scope_name(op)
            for region in op.regions:

        default: Optional[int] = None,
    ) -> int:
        """Read operand ``index`` from ``<env>``, or get stuck."""
        operands = op.operands
        if index >= len(operands):
            if default is None:
                raise StuckError(f"'{op.name}' has no operand {index}")
            return int(default)
        value = config.lookup(operands[index])
        if value is None:
            if default is not None:
                return int(default)
            raise StuckError(f"operand {index} of '{op.name}' is unbound")
        return int(value)

    def read_all(self, op: Operation, config: KConfiguration) -> List[int]:
        return [self.read(op, config, index) for index in range(len(op.operands))]

    # -- result handling --------------------------------------------------
    def width(self, op: Operation) -> int:
        return _result_width(op)

    def truncate(self, op: Operation, value: int) -> int:
        width = self.width(op)
        return int(value) & ((1 << width) - 1) if width > 0 else int(value)

    def bind(self, op: Operation, config: KConfiguration, value: int) -> int:
        """Bind ``value`` to every result of ``op`` (and to its SSA name)."""
        for result in op.results:
            config.bind(result, value)
            if result.name:
                config.bind(result.name, value)
        return value

    def label(self, op: Operation) -> str:
        names = [f"%{r.name}" for r in op.results if r.name]
        return ", ".join(names)

    # -- application ------------------------------------------------------
    def compute(self, op: Operation, config: KConfiguration) -> int:
        """The rule's arithmetic.  Overridden by every concrete rule."""
        raise NotImplementedError(f"{self.NAME} does not implement compute()")

    def apply(
        self, op: Optional[Operation], config: KConfiguration
    ) -> RuleApplication:
        """Fire the rule, rewriting ``config``, and return the trace record."""
        assert op is not None, f"{self.NAME} needs an operation"
        operands = tuple(self.read_all(op, config))
        value = self.truncate(op, self.compute(op, config))
        self.bind(op, config, value)
        return RuleApplication(
            rule=self.NAME,
            op_name=op.name,
            label=self.label(op),
            operands=operands,
            result=value,
            cycle=config.cycle,
            phase=self.PHASE,
        )

    # -- reporting --------------------------------------------------------
    def describe(self) -> str:
        rule = self.K_RULE.strip() or f"rule {self.NAME}"
        targets = ", ".join(self.OP_NAMES) or "<configuration>"
        return f"{self.NAME} [{self.PHASE.value}] on {targets}\n    {rule}"

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<{type(self).__name__} {self.NAME!r}>"


